;------------------------------------------------------------------------------
; ShopPub: "Have a drink! It costs 7 g.p." The player pays a two-digit amount (BCD);
; less than 7 is refused, at least all his gold is "Can't pay". The barkeeper then tells the
; tip PubTips[tens digit of the amount]: 7-9 gp only thanks, 10-19 the first rumour, ...
; 90-99 the last. "Another?" repeats. In: DI = the paying player's record.
;------------------------------------------------------------------------------
ShopPub:	pushf	;@A5AC
	push ax	;@A5AD
	push cx	;@A5AE
	push dx	;@A5AF
	push si	;@A5B0
	lea si, MsgWelcomePub	;@A5B1
	call PrintMsg	;@A5B5
ShopPub_Again:	lea si, MsgHaveADrink	;@A5B8
	call PrintMsg	;@A5BC
	call ReadNumber	; AL = amount (BCD), AH = 0FFh: Esc	;@A5BF
	cmp ah, 0FFh	;@A5C2
	je ShopPub_Cancel	;@A5C5
	call ScrollMsg	;@A5C7
	cmp al, 7	; less than 7 g.p.?	;@A5CA
	jae ShopPub_Pay	;@A5CC
	lea si, MsgLeaveMyShop	;@A5CE
	call PrintMsg	;@A5D2
	mov al, 0FFh	; failure sound	;@A5D5
	call Sound	;@A5D7
	jmp short ShopPub_Done	;@A5DA
ShopPub_Pay:	mov ah, 0	;@A5DC
	cmp ax, word ptr [di+23h]	; amount >= gold: can't pay (even exactly all of it)	;@A5DE
	jae ShopPub_CantPay	;@A5E1
	call ScrollMsg	;@A5E3
	call PayGold	; PayGold: AX = amount	;@A5E6
	mov cl, 4	; the tens digit ...	;@A5E9
	shr ax, cl	;@A5EB
	mov si, ax	; ... selects the tip	;@A5ED
	shl si, 1	;@A5EF
	mov si, word ptr PubTips[si]	;@A5F1
	call PrintMsg	;@A5F5
	lea si, MsgAnother	;@A5F8
	call PrintMsg	;@A5FC
	call AskYesNo	; AskYesNo	;@A5FF
	call ScrollMsg	;@A602
	cmp al, 59h	; 'Y'	;@A605
	je ShopPub_Again	;@A607
	lea si, MsgBeenAPleasure	;@A609
	call PrintMsg	;@A60D
ShopPub_Done:	pop si	;@A610
	pop dx	;@A611
	pop cx	;@A612
	pop ax	;@A613
	popf	;@A614
	ret	;@A615
ShopPub_CantPay:	lea si, MsgCantPay	;@A616
	call PrintMsg	;@A61A
	jmp short ShopPub_Beep	;@A61D
ShopPub_Cancel:	call ScrollMsg	;@A61F
	lea si, TxtWhat	; the cancel message of HAND (TxtWhat)	;@A622
	call PrintMsg	;@A626
ShopPub_Beep:	mov al, 0FEh	; refused sound	;@A629
	call Sound	;@A62B
	jmp ShopPub_Done	;@A62E
;------------------------------------------------------------------------------
; ShopGrocer: rations at 1 g.p. each. Reads up to four digits (EQUIP ReadAmount: AX = BCD
; number); refuses more than the gold, adds them to the food word [di+21h] (BCD; a carry out of
; 9999 is "Too much to carry!" and undoes it), then pays.
; In: DI = the buyer's record.
;------------------------------------------------------------------------------
ShopGrocer:	pushf	;@A630
	push ax	;@A631
	push si	;@A632
	lea si, MsgGrocer	;@A633
	call PrintMsg	;@A637
	call ReadAmount	; AX = number of rations (BCD), 0 = none	;@A63A
	cmp ax, 0	;@A63D
	je ShopGrocer_Thanks	;@A640
	cmp ax, word ptr [di+23h]	; more than his gold?	;@A642
	ja ShopGrocer_CantPay	;@A645
	push word ptr [di+21h]	; keep the old food	;@A647
	xchg word ptr [di+21h], ax	; food (21-22, BCD word) += rations	;@A64A
	add al, byte ptr [di+21h]	;@A64D
	daa	;@A650
	xchg al, ah	;@A651
	adc al, byte ptr [di+22h]	;@A653
	daa	;@A656
	xchg al, ah	;@A657
	xchg word ptr [di+21h], ax	;@A659
	jb ShopGrocer_TooMuch	; past 9999: too much	;@A65C
	add sp, 2	; drop the saved food	;@A65E
	call PayGold	; PayGold: 1 g.p. a ration	;@A661
	call StatusLine	;@A664
ShopGrocer_Thanks:	lea si, MsgGrocerThanks	;@A667
	call PrintMsg	;@A66B
ShopGrocer_Done:	pop si	;@A66E
	pop ax	;@A66F
	popf	;@A670
	ret	;@A671
ShopGrocer_CantPay:	lea si, MsgCantPay	;@A672
	call PrintMsg	;@A676
	mov al, 0FFh	;@A679
	call Sound	;@A67B
	jmp ShopGrocer_Done	;@A67E
ShopGrocer_TooMuch:	lea si, MsgTooMuchToCarry	;@A680
	call PrintMsg	;@A684
	pop ax	;@A687
	mov word ptr [di+21h], ax	; put the old food back	;@A688
	mov al, 0FFh	;@A68B
	call Sound	;@A68D
	jmp ShopGrocer_Done	;@A690
;------------------------------------------------------------------------------
; ShopTemple: the clerical sacraments: 1 cure (TempleCure), 2 heal (TempleHeal),
; 3 resurrect (TempleResurrect), 4 recall (TempleRecall), through TempleCmds (TEXT TempleCmds);
; Q or Esc leaves. The four services return through ShopTemple_Farewell or _Done, which pop
; what ShopTemple pushed. In: DI = the paying player's record.
;------------------------------------------------------------------------------
ShopTemple:	pushf	;@A692
	push ax	;@A693
	push bx	;@A694
	push cx	;@A695
	push si	;@A696
	lea si, MsgSacraments	;@A697
	call PrintMsg	;@A69B
	push di	;@A69E
	mov cx, 6	; six keys: 1 2 3 4 Q Esc	;@A69F
	lea si, TempleMenuStrs	;@A6A2
	lea di, TempleMenuKeys	;@A6A6
	call AskChoice	;@A6AA
	pop di	;@A6AD
	cmp al, 51h	;@A6AE
	je ShopTemple_Farewell	;@A6B0
	cmp al, 1Bh	;@A6B2
	je ShopTemple_Farewell	;@A6B4
	dec al	; '1'-'4' -> 0-3	;@A6B6
	and al, 3	;@A6B8
	mov ah, 0	;@A6BA
	mov bx, ax	;@A6BC
	shl bx, 1	;@A6BE
	jmp word ptr TempleCmds[bx]	;@A6C0
ShopTemple_Farewell:	lea si, MsgFareTheeWell	;@A6C4
	call PrintMsg	;@A6C8
	call StatusLine	;@A6CB
ShopTemple_Done:	pop si	;@A6CE
	pop cx	;@A6CF
	pop bx	;@A6D0
	pop ax	;@A6D1
	popf	;@A6D2
	ret	;@A6D3
;------------------------------------------------------------------------------
; TempleCure: 100 g.p. to cure poison. The target must not be Good ("Not injured!");
; if he is Poisoned he becomes Good and the payer pays, otherwise (dead, ashes) "Failed!"
; and nothing is paid. In: DI = payer (pushed state of ShopTemple on the stack).
;------------------------------------------------------------------------------
TempleCure:	lea si, MsgCuringCost	;@A6D4
	call PrintMsg	;@A6D8
	call AskYesNo	; AskYesNo	;@A6DB
	cmp al, 4Eh	; 'N'	;@A6DE
	je ShopTemple_NoOffering	;@A6E0
	cmp word ptr [di+23h], 100h	; gold (23-24, BCD) < 100?	;@A6E2
	jb ShopTemple_NoGold	;@A6E7
	lea si, MsgTempleCureWhom	;@A6E9
	call PrintMsg	;@A6ED
	call AskPlayer	; BX = the target's record, AL = 1-4; ZF: Esc	;@A6F0
	je ShopTemple_Done	;@A6F3
	dec al	;@A6F5
	mov cx, ax	;@A6F7
	cmp byte ptr [bx+11h], 47h	; status (11h) 'G' good	;@A6F9
	je ShopTemple_NotInjured	;@A6FD
	mov ax, cx	; the target's number (0-3)	;@A6FF
	call FlashView	; flash the map window (PARTY FlashView) and his status line (FlashPlayer) ?	;@A701
	call FlashPlayer	;@A704
	push bx	;@A707
	mov al, 0FDh	; the temple's sound	;@A708
	mov bl, 0C0h	;@A70A
	mov bh, 80h	;@A70C
	call Sound	;@A70E
	pop bx	;@A711
	mov ax, cx	;@A712
	call FlashPlayer	; flash both back	;@A714
	call FlashView	;@A717
	cmp byte ptr [bx+11h], 50h	; 'P' poisoned?	;@A71A
	jne ShopTemple_Failed	;@A71E
	mov byte ptr [bx+11h], 47h	; status = 'G'	;@A720
	mov ax, 100h	; 100 g.p. (BCD)	;@A724
	call PayGold	;@A727
	jmp ShopTemple_Farewell	;@A72A
ShopTemple_NoOffering:	lea si, MsgNoOfferings	;@A72C
	call PrintMsg	;@A730
	jmp ShopTemple_Done	;@A733
ShopTemple_NoGold:	lea si, MsgNotGoldEnough	;@A735
	call PrintMsg	;@A739
	mov al, 0FFh	;@A73C
	call Sound	;@A73E
	jmp ShopTemple_Done	;@A741
ShopTemple_NotInjured:	lea si, MsgNotInjured	;@A743
	call PrintMsg	;@A747
	mov al, 0FFh	;@A74A
	call Sound	;@A74C
	jmp ShopTemple_Done	;@A74F
ShopTemple_Failed:	lea si, MsgTempleFailed	;@A752
	call PrintMsg	;@A756
	mov al, 0FFh	;@A759
	call Sound	;@A75B
	jmp ShopTemple_Done	;@A75E
;------------------------------------------------------------------------------
; TempleHeal: 200 g.p.: hit points = maximum hit points. "Not injured!" only when
; the hit points are above the maximum: a player at full hit points is healed and charged,
; and the status is not looked at (a dead player is healed too, still dead). In: DI = payer.
;------------------------------------------------------------------------------
TempleHeal:	lea si, MsgHealingCost	;@A761
	call PrintMsg	;@A765
	call AskYesNo	;@A768
	cmp al, 4Eh	;@A76B
	je ShopTemple_NoOffering	;@A76D
	cmp word ptr [di+23h], 200h	; gold < 200?	;@A76F
	jb ShopTemple_NoGold	;@A774
	lea si, MsgTempleHealWhom	;@A776
	call PrintMsg	;@A77A
	call AskPlayer	;@A77D
	jne TempleHeal_Player	;@A780
	jmp ShopTemple_Done	;@A782
TempleHeal_Player:	dec al	;@A785
	mov cx, ax	;@A787
	mov ax, word ptr [bx+1Ch]	; maximum hit points (1C-1D)	;@A789
	cmp ax, word ptr [bx+1Ah]	; hit points (1A-1B)	;@A78C
	jb ShopTemple_NotInjured	;@A78F
	mov word ptr [bx+1Ah], ax	; hit points = maximum	;@A791
	mov ax, cx	;@A794
	call FlashView	;@A796
	call FlashPlayer	;@A799
	mov al, 0FDh	;@A79C
	mov bl, 0C0h	;@A79E
	mov bh, 80h	;@A7A0
	call Sound	;@A7A2
	mov ax, cx	;@A7A5
	call FlashPlayer	;@A7A7
	call FlashView	;@A7AA
	mov ax, 200h	; 200 g.p. (BCD)	;@A7AD
	call PayGold	;@A7B0
	jmp ShopTemple_Farewell	;@A7B3
;------------------------------------------------------------------------------
; TempleResurrect: 500 g.p.: Dead -> Good (the hit points are not changed). Good:
; "Not injured!", Poisoned: "Not dead!", Ashes: "Failed!" after the flash. In: DI = payer.
;------------------------------------------------------------------------------
TempleResurrect:	lea si, MsgResurrectCost	;@A7B6
	call PrintMsg	;@A7BA
	call AskYesNo	;@A7BD
	cmp al, 4Eh	;@A7C0
	jne TempleResurrect_HasGold	;@A7C2
	jmp ShopTemple_NoOffering	;@A7C4
TempleResurrect_HasGold:	cmp word ptr [di+23h], 500h	; gold >= 500?	;@A7C7
	jae TempleResurrect_Ask	;@A7CC
	jmp ShopTemple_NoGold	;@A7CE
TempleResurrect_Ask:	lea si, MsgTempleResurrectWhom	;@A7D1
	call PrintMsg	;@A7D5
	call AskPlayer	;@A7D8
	jne TempleResurrect_Player	;@A7DB
	jmp ShopTemple_Done	;@A7DD
TempleResurrect_Player:	dec al	;@A7E0
	mov cx, ax	;@A7E2
	cmp byte ptr [bx+11h], 47h	; 'G' good	;@A7E4
	jne TempleResurrect_NotGood	;@A7E8
	jmp ShopTemple_NotInjured	;@A7EA
TempleResurrect_NotGood:	cmp byte ptr [bx+11h], 50h	; 'P' poisoned	;@A7ED
	je TempleResurrect_NotDead	;@A7F1
	mov ax, cx	;@A7F3
	call FlashView	;@A7F5
	call FlashPlayer	;@A7F8
	push bx	;@A7FB
	mov al, 0FDh	;@A7FC
	mov bl, 0C0h	;@A7FE
	mov bh, 80h	;@A800
	call Sound	;@A802
	pop bx	;@A805
	mov ax, cx	;@A806
	call FlashPlayer	;@A808
	call FlashView	;@A80B
	cmp byte ptr [bx+11h], 44h	; 'D' dead?	;@A80E
	je TempleResurrect_Dead	;@A812
	jmp ShopTemple_Failed	;@A814
TempleResurrect_Dead:	mov byte ptr [bx+11h], 47h	; status = 'G'	;@A817
	mov ax, 500h	; 500 g.p. (BCD)	;@A81B
	call PayGold	;@A81E
	jmp ShopTemple_Farewell	;@A821
TempleResurrect_NotDead:	lea si, MsgNotDead	;@A824
	call PrintMsg	;@A828
	mov al, 0FFh	;@A82B
	call Sound	;@A82D
	jmp ShopTemple_Done	;@A830
;------------------------------------------------------------------------------
; TempleRecall: 900 g.p.: Ashes -> Good. Good: "Not injured!", anything else but
; Ashes: "Not ashes!". In: DI = payer.
;------------------------------------------------------------------------------
TempleRecall:	lea si, MsgRecallCost	;@A833
	call PrintMsg	;@A837
	call AskYesNo	;@A83A
	cmp al, 4Eh	;@A83D
	jne TempleRecall_HasGold	;@A83F
	jmp ShopTemple_NoOffering	;@A841
TempleRecall_HasGold:	cmp word ptr [di+23h], 900h	; gold >= 900?	;@A844
	jae TempleRecall_Ask	;@A849
	jmp ShopTemple_NoGold	;@A84B
TempleRecall_Ask:	lea si, MsgTempleRecallWhom	;@A84E
	call PrintMsg	;@A852
	call AskPlayer	;@A855
	jne TempleRecall_Player	;@A858
	jmp ShopTemple_Done	;@A85A
TempleRecall_Player:	dec al	;@A85D
	mov cx, ax	;@A85F
	cmp byte ptr [bx+11h], 47h	; 'G' good	;@A861
	jne TempleRecall_NotGood	;@A865
	jmp ShopTemple_NotInjured	;@A867
TempleRecall_NotGood:	cmp byte ptr [bx+11h], 41h	; 'A' ashes?	;@A86A
	jne TempleRecall_NotAshes	;@A86E
	mov byte ptr [bx+11h], 47h	; status = 'G'	;@A870
	mov ax, cx	;@A874
	call FlashView	;@A876
	call FlashPlayer	;@A879
	mov al, 0FDh	;@A87C
	mov bl, 0C0h	;@A87E
	mov bh, 80h	;@A880
	call Sound	;@A882
	mov ax, cx	;@A885
	call FlashPlayer	;@A887
	call FlashView	;@A88A
	mov ax, 900h	; 900 g.p. (BCD)	;@A88D
	call PayGold	;@A890
	jmp ShopTemple_Farewell	;@A893
TempleRecall_NotAshes:	lea si, MsgNotAshes	;@A896
	call PrintMsg	;@A89A
	mov al, 0FFh	;@A89D
	call Sound	;@A89F
	jmp ShopTemple_Done	;@A8A2
;------------------------------------------------------------------------------
; ShopWeapons: "List?" (ShopListWeapons), then "Buy or sell?" until Q or Esc.
; Keys B-H choose Dagger ... 2H Swd; in Dawn, once the list has been shown there
; (ExtraWeaponsOk set), B-O. Buying adds one to the count at [di+31h+n] (at most 99) and pays
; WeaponPrices[n]; selling gives the same full price back (the gold may not pass 9999),
; takes one away and sets the readied weapon to Hand, whichever weapon was sold.
; In: DI = the player's record.
;------------------------------------------------------------------------------
ShopWeapons:	pushf	;@A8A5
	push ax	;@A8A6
	push bx	;@A8A7
	push cx	;@A8A8
	push dx	;@A8A9
	push si	;@A8AA
	push di	;@A8AB
	lea si, MsgWeaponsShop	;@A8AC
	call PrintMsg	;@A8B0
	call AskYesNo	; AskYesNo: List?	;@A8B3
	cmp al, 4Eh	;@A8B6
	je ShopWeapons_BuySell	;@A8B8
	call ShopListWeapons	;@A8BA
ShopWeapons_BuySell:	lea si, MsgBuyOrSell	;@A8BD
	call PrintMsg	;@A8C1
	push di	;@A8C4
	mov cx, 4	; four keys: B S Q Esc	;@A8C5
	lea si, BuySellMenuStrs	;@A8C8
	lea di, BuySellMenuKeys	;@A8CC
	call AskChoice	;@A8D0
	pop di	;@A8D3
	call ScrollMsg	;@A8D4
	cmp al, 51h	;@A8D7
	je ShopWeapons_Done	;@A8D9
	cmp al, 1Bh	;@A8DB
	je ShopWeapons_Done	;@A8DD
	cmp al, 42h	; 'B' buy	;@A8DF
	jne ShopWeapons_Sell	;@A8E1
	jmp ShopWeapons_Buy	;@A8E3
ShopWeapons_Sell:	lea si, MsgForSale	;@A8E6
	call PrintMsg	;@A8EA
	push di	;@A8ED
	mov cx, 0Ah	; weapon keys Q Esc 0 B-H	;@A8EE
	cmp byte ptr PartyXY, 25h	; in Dawn?	;@A8F1
	jne ShopWeapons_SellMenu	;@A8F6
	cmp byte ptr ExtraWeaponsOk, 0	; and the list was shown there	;@A8F8
	je ShopWeapons_SellMenu	;@A8FD
	mov cx, 11h	; Q Esc 0 B-O	;@A8FF
ShopWeapons_SellMenu:	lea si, WeaponMenuStrs	; pointer table of the weapon menu (ACTIONS)	;@A902
	lea di, ShopWeaponKeys	;@A906
	call AskChoice	;@A90A
	pop di	;@A90D
	cmp al, 51h	;@A90E
	je ShopWeapons_Scroll	;@A910
	cmp al, 1Bh	;@A912
	je ShopWeapons_Scroll	;@A914
	sub al, 42h	; 'B' = weapon 1 (Dagger)	;@A916
	mov bx, ax	;@A918
	mov bh, 0	;@A91A
	mov al, byte ptr [bx+di+31h]	; count owned of that weapon (31h-3Fh)	;@A91C
	cmp al, 0	;@A91F
