;------------------------------------------------------------------------------
; ShopGuild: "The Guild shop": G gems 75, K keys 50, P powders 90, T torches 6 g.p.
; each, through GuildCmds (TEXT GuildCmds); Q and Esc go to GuildDone. Each purchase asks
; "How many?" (two digits), refuses a total over 99 ("Too much to carry!") or a price over
; the gold, and offers "Anything else?". In: DI = the buyer's record.
;------------------------------------------------------------------------------
ShopGuild:	pushf	;@AB93
	push ax	;@AB94
	push cx	;@AB95
	push si	;@AB96
	push di	;@AB97
ShopGuild_Menu:	lea si, MsgGuildShop	;@AB98
	call PrintMsg	;@AB9C
	push di	;@AB9F
	lea si, GuildMenuStrs	;@ABA0
	lea di, GuildMenuKeys	;@ABA4
	mov cx, 6	; six keys: G K P T Q Esc	;@ABA8
	call AskChoice	;@ABAB
	repne scasb	; AskChoice keeps DI and CX: find the key again	;@ABAE
	mov bx, 6	; BX = its index * 2	;@ABB0
	sub bx, cx	;@ABB3
	dec bx	;@ABB5
	shl bx, 1	;@ABB6
	pop di	;@ABB8
	jmp word ptr GuildCmds[bx]	;@ABB9
;------------------------------------------------------------------------------
; GuildGems, GuildKeys, GuildPowders, GuildTorches: buy AL
; (BCD, from ReadNumber; AH = the same number in binary) items at 75, 50, 90 or 6 g.p.
; The price is computed in binary, rate * count, and turned into a BCD word: hundreds in AH,
; the rest in AL. Gems at [di+25h], keys 26h, powders 27h, torches 0Fh (all BCD bytes).
;------------------------------------------------------------------------------
GuildGems:	lea si, MsgGuildHowMany	;@ABBD
	call PrintMsg	;@ABC1
	call ReadNumber	; AL = count (BCD), AH = count (binary), 0FFh: Esc	;@ABC4
	cmp ah, 0FFh	;@ABC7
	jne GuildGems_Price	;@ABCA
	jmp ShopGuild_Cancel	;@ABCC
GuildGems_Price:	mov bx, ax	;@ABCF
	add al, byte ptr [di+25h]	; gems (25h) + count	;@ABD1
	daa	;@ABD4
	mov bl, al	;@ABD5
	jb ShopGuild_TooMuch	; over 99	;@ABD7
	mov al, 4Bh	; 75 g.p. a gem, times the binary count	;@ABD9
	mul bh	;@ABDB
	mov cl, 64h	; / 100: AL = hundreds, AH = the rest	;@ABDD
	div cl	;@ABDF
	mov cx, ax	;@ABE1
	mov cl, 4	;@ABE3
	aam	; hundreds to BCD	;@ABE5
	shl ah, cl	;@ABE7
	or al, ah	;@ABE9
	xchg ch, al	;@ABEB
	aam	; the rest to BCD	;@ABED
	shl ah, cl	;@ABEF
	or al, ah	;@ABF1
	mov ah, ch	; AX = price (BCD word)	;@ABF3
	call PayGold	; PayGold; CF: not enough	;@ABF5
	jb ShopGuild_NoFunds	;@ABF8
	mov byte ptr [di+25h], bl	; new number of gems	;@ABFA
	jmp short ShopGuild_More	;@ABFD
; GuildKeys: keys at [di+26h], 50 g.p. each.
GuildKeys:	lea si, MsgGuildHowMany	;@ABFF
	call PrintMsg	;@AC03
	call ReadNumber	;@AC06
	cmp ah, 0FFh	;@AC09
	je ShopGuild_Cancel	;@AC0C
	mov bx, ax	;@AC0E
	add al, byte ptr [di+26h]	; keys (26h) + count	;@AC10
	daa	;@AC13
	mov bl, al	;@AC14
	jb ShopGuild_TooMuch	;@AC16
	mov al, 32h	; 50 g.p. a key	;@AC18
	mul bh	;@AC1A
	mov cl, 64h	;@AC1C
	div cl	;@AC1E
	mov cx, ax	;@AC20
	mov cl, 4	;@AC22
	aam	;@AC24
	shl ah, cl	;@AC26
	or al, ah	;@AC28
	xchg ch, al	;@AC2A
	aam	;@AC2C
	shl ah, cl	;@AC2E
	or al, ah	;@AC30
	mov ah, ch	;@AC32
	call PayGold	;@AC34
	jb ShopGuild_NoFunds	;@AC37
	mov byte ptr [di+26h], bl	; new number of keys	;@AC39
ShopGuild_More:	lea si, MsgAnythingElse	;@AC3C
	call PrintMsg	;@AC40
	call AskYesNo	; AskYesNo: Anything else?	;@AC43
	cmp al, 4Eh	;@AC46
	je ShopGuild_Thanks	;@AC48
	jmp ShopGuild_Menu	;@AC4A
ShopGuild_Thanks:	jmp GuildDone	;@AC4D
ShopGuild_TooMuch:	lea si, MsgTooMuchToCarry	;@AC50
	call PrintMsg	;@AC54
	jmp short ShopGuild_Beep	;@AC57
ShopGuild_NoFunds:	lea si, MsgNotTheFunds	;@AC59
	call PrintMsg	;@AC5D
ShopGuild_Cancel:	call ScrollMsg	;@AC60
ShopGuild_Beep:	mov al, 0FFh	;@AC63
	call Sound	;@AC65
	jmp ShopGuild_Done	;@AC68
; GuildPowders: powders at [di+27h], 90 g.p. each.
GuildPowders:	lea si, MsgGuildHowMany	;@AC6B
	call PrintMsg	;@AC6F
	call ReadNumber	;@AC72
	cmp ah, 0FFh	;@AC75
	je ShopGuild_Cancel	;@AC78
	mov bx, ax	;@AC7A
	add al, byte ptr [di+27h]	; powders (27h) + count	;@AC7C
	daa	;@AC7F
	mov bl, al	;@AC80
	jb ShopGuild_TooMuch	;@AC82
	mov al, 5Ah	; 90 g.p. a powder	;@AC84
	mul bh	;@AC86
	mov cl, 64h	;@AC88
	div cl	;@AC8A
	mov cx, ax	;@AC8C
	mov cl, 4	;@AC8E
	aam	;@AC90
	shl ah, cl	;@AC92
	or al, ah	;@AC94
	xchg ch, al	;@AC96
	aam	;@AC98
	shl ah, cl	;@AC9A
	or al, ah	;@AC9C
	mov ah, ch	;@AC9E
	call PayGold	;@ACA0
	jae GuildPowders_Paid	;@ACA3
	jmp ShopGuild_NoFunds	;@ACA5
GuildPowders_Paid:	mov byte ptr [di+27h], bl	; new number of powders	;@ACA7
	jmp ShopGuild_More	;@ACAA
; GuildTorches: torches at [di+0Fh], 6 g.p. each.
GuildTorches:	lea si, MsgGuildHowMany	;@ACAC
	call PrintMsg	;@ACB0
	call ReadNumber	;@ACB3
	cmp ah, 0FFh	;@ACB6
	je ShopGuild_Cancel	;@ACB9
	mov bx, ax	;@ACBB
	add al, byte ptr [di+0Fh]	; torches (0Fh) + count	;@ACBD
	daa	;@ACC0
	mov bl, al	;@ACC1
	jb ShopGuild_TooMuch	;@ACC3
	mov al, 6	; 6 g.p. a torch	;@ACC5
	mul bh	;@ACC7
	mov cl, 64h	;@ACC9
	div cl	;@ACCB
	mov cx, ax	;@ACCD
	mov cl, 4	;@ACCF
	aam	;@ACD1
	shl ah, cl	;@ACD3
	or al, ah	;@ACD5
	xchg ch, al	;@ACD7
	aam	;@ACD9
	shl ah, cl	;@ACDB
	or al, ah	;@ACDD
	mov ah, ch	;@ACDF
	call PayGold	;@ACE1
	jae GuildTorches_Paid	;@ACE4
	jmp ShopGuild_NoFunds	;@ACE6
GuildTorches_Paid:	mov byte ptr [di+0Fh], bl	; new number of torches	;@ACE9
	jmp ShopGuild_More	;@ACEC
; GuildDone: "Thank you, come again!" and leave the Guild.
GuildDone:	lea si, MsgGuildThanks	;@ACEF
	call PrintMsg	;@ACF3
ShopGuild_Done:	pop di	;@ACF6
	pop si	;@ACF7
	pop cx	;@ACF8
	pop ax	;@ACF9
	popf	;@ACFA
	ret	;@ACFB
;------------------------------------------------------------------------------
; ShopRadrion: "Radrion: Prophet of Life!" The player offers a two-digit number of
; hundreds of gold; the verse told is OracleVerses[that number], read as BCD: offers of 0-9
; hundred give verse 0-9 (0 is free), but 10 or more index past the 10-entry table (bug:
; the pointer is taken from the strings that follow). "More offering?" repeats.
; In: DI = the paying player's record.
;------------------------------------------------------------------------------
ShopRadrion:	pushf	;@ACFC
	push ax	;@ACFD
	push cx	;@ACFE
	push dx	;@ACFF
	push si	;@AD00
	lea si, MsgRadrion	;@AD01
	call PrintMsg	;@AD05
ShopRadrion_Ask:	lea si, MsgHowMany100gp	;@AD08
	call PrintMsg	;@AD0C
	call ReadNumber	; AL = hundreds (BCD), AH = 0FFh: Esc	;@AD0F
	cmp ah, 0FFh	;@AD12
	je ShopRadrion_Cancel	;@AD15
	call ScrollMsg	;@AD17
	call ScrollMsg	;@AD1A
	mov ah, al	; AX = hundreds * 100 (BCD word)	;@AD1D
	mov al, 0	;@AD1F
	call PayGold	; PayGold; CF: not enough	;@AD21
	jb ShopRadrion_CantPay	;@AD24
	mov cl, 8	; AH (BCD hundreds) ...	;@AD26
	shr ax, cl	;@AD28
	mov si, ax	; ... selects the verse	;@AD2A
	shl si, 1	;@AD2C
	mov si, word ptr OracleVerses[si]	;@AD2E
	call PrintMsg	;@AD32
	lea si, MsgMoreOffering	;@AD35
	call PrintMsg	;@AD39
	call AskYesNo	; AskYesNo	;@AD3C
	call ScrollMsg	;@AD3F
	cmp al, 59h	; 'Y'	;@AD42
	je ShopRadrion_Ask	;@AD44
	call ScrollMsg	;@AD46
	lea si, MsgGoodLuck	;@AD49
	call PrintMsg	;@AD4D
ShopRadrion_Done:	pop si	;@AD50
	pop dx	;@AD51
	pop cx	;@AD52
	pop ax	;@AD53
	popf	;@AD54
	ret	;@AD55
ShopRadrion_CantPay:	lea si, MsgCantPay	;@AD56
	call PrintMsg	;@AD5A
	jmp short ShopRadrion_Beep	;@AD5D
ShopRadrion_Cancel:	call ScrollMsg	;@AD5F
	lea si, TxtWhat	; the cancel message of HAND (TxtWhat)	;@AD62
	call PrintMsg	;@AD66
ShopRadrion_Beep:	mov al, 0FEh	;@AD69
	call Sound	;@AD6B
	jmp ShopRadrion_Done	;@AD6E
;------------------------------------------------------------------------------
; ShopHorses: the Equine Emporium: PartySize horses for PartySize * 200 g.p.; on
; payment the party's tile becomes the horse. Also called by EQUIP (8018), from talking to
; a merchant (?). In: DI = the paying player's record.
;------------------------------------------------------------------------------
ShopHorses:	pushf	;@AD70
	push ax	;@AD71
	push si	;@AD72
	lea si, MsgEquineEmporium	;@AD73
	call PrintMsg	;@AD77
	mov al, byte ptr PartySize	;@AD7A
	call PrintDigit	; "n horses cost"	;@AD7D
	lea si, MsgHorsesCost	;@AD80
	call PrintMsg	;@AD84
	shl al, 1	; 2n: "2n00gp" (one digit: up to 8)	;@AD87
	call PrintDigit	;@AD89
	lea si, MsgWillYouBuy	;@AD8C
	call PrintMsg	;@AD90
	mov ah, al	; AH = 2n (BCD hundreds)	;@AD93
	call AskYesNo	;@AD95
	cmp al, 4Eh	;@AD98
	je ShopHorses_Declined	;@AD9A
	mov al, 0	; AX = 2n * 100 (BCD)	;@AD9C
	call PayGold	; PayGold	;@AD9E
	jb ShopHorses_NoGold	;@ADA1
	lea si, MsgRideFast	;@ADA3
	call PrintMsg	;@ADA7
	mov byte ptr PartyTile, 0Ah	; the party's tile: 0Ah horse	;@ADAA
	jmp short ShopHorses_Done	;@ADAF
ShopHorses_NoGold:	lea si, MsgNotGoldEnough	;@ADB1
	call PrintMsg	;@ADB5
	mov al, 0FFh	;@ADB8
	call Sound	;@ADBA
	jmp short ShopHorses_Done	;@ADBD
ShopHorses_Declined:	lea si, MsgTooBad	;@ADBF
	call PrintMsg	;@ADC3
ShopHorses_Done:	pop si	;@ADC6
	pop ax	;@ADC7
	popf	;@ADC8
	ret	;@ADC9
CODE ENDS
END
